// AF-NEXT-007 × AF-NEXT-009 end to end (frontend half): the Preflight panel's runPreflight
// loads the real engineering/showDiagnostics.js, which posts the show to
// /hydraulics/show-timeline. The response is the backend evaluator's recorded output for the
// same request (golden/overload-timeline.json, generated by services/show_hydraulics.py), so
// an overloaded pump must surface as a preflight issue with its timestamp and fix target.
import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import path from "node:path";
import { runPreflight } from "../preflight.js";
import { buildShowTimelinePayload, clearShowTimelineCache } from "../../engineering/showHydraulicsClient.js";
import { overloadedPumpProject } from "./hydraulicsPreflight.fixture.js";

const GOLDEN = path.join(__dirname, "golden", "overload-timeline.json");

describe("preflight × hydraulics", () => {
  afterEach(() => { vi.unstubAllGlobals(); clearShowTimelineCache(); });

  it("the request the panel sends is the one the golden was generated from", () => {
    const request = buildShowTimelinePayload(overloadedPumpProject(), overloadedPumpProject(), {});
    if (process.env.UPDATE_GOLDEN) {
      fs.mkdirSync(path.dirname(GOLDEN), { recursive: true });
      const old = fs.existsSync(GOLDEN) ? JSON.parse(fs.readFileSync(GOLDEN, "utf8")) : {};
      fs.writeFileSync(GOLDEN, JSON.stringify({ ...old, request }, null, 1));
    }
    expect(JSON.parse(fs.readFileSync(GOLDEN, "utf8")).request).toEqual(JSON.parse(JSON.stringify(request)));
  });

  it("an overloaded pump appears as a preflight issue (assumed curve → warning, gate stays open)", async () => {
    const golden = JSON.parse(fs.readFileSync(GOLDEN, "utf8"));
    const calls = [];
    vi.stubGlobal("fetch", vi.fn(async (url, init) => {
      calls.push(String(url));
      const body = String(url).endsWith("/hydraulics/show-timeline") ? golden.response : { ok: true, issues: [] };
      return { ok: true, json: async () => body };
    }));
    const result = await runPreflight(overloadedPumpProject(), { kind: "preview" },
      { fetchImpl: async () => ({ ok: true, json: async () => ({ ok: true, issues: [] }) }) });
    expect(calls.some(u => u.endsWith("/hydraulics/show-timeline"))).toBe(true);
    const over = result.issues.find(i => i.code === "PUMP_OVERLOAD");
    // The pump only has a duty point (assumed generic curve): overload is a warning asking for
    // verified pump data and does not block output. With verified/measured curve data the backend
    // reports it as an error (backend test_overload_severity_follows_curve_verification).
    expect(over).toMatchObject({ severity: "warning", source: "hydraulics", engineeringItemId: "P1",
      fix: { kind: "open_engineering_item", target: "P1" } });
    expect(over.message).toMatch(/enter verified pump curve data/);
    expect(typeof over.timeMs).toBe("number");
    expect(over.clipId).toMatch(/^r\d:N\d:0$/);
    expect(result.issues.filter(i => i.severity === "error")).toEqual([]);
    expect(result.ok).toBe(true);
    expect(result.issues.some(i => i.code === "NOZZLE_UNDER_PRESSURE")).toBe(true);
    // splash ran too (vertical jets, calm air, in the basin): nothing to report
    expect(result.issues.some(i => i.source === "splash" && i.code === "SPLASH_OUTSIDE_BASIN")).toBe(false);
  });
});
